add('11:Review Questions',[
{id:'ch11-rev-1',title:'Beam versus plate girder',level:'foundation',kind:'retrieval',q:'What fundamental distinction should you be able to state after reviewing Chapter 11?',choices:['A plate girder is a custom built-up deep flexural member, unlike a fixed catalogue rolled beam','A plate girder carries no shear','A rolled beam has no flange','Only plate girders are made from steel'],answer:0,explanation:'The review begins with the purpose and structural form of plate girders.',source:S},
{id:'ch11-rev-2',title:'Web buckling recall',level:'core',kind:'retrieval',q:'What is the key instability associated with a deep slender plate-girder web under high shear?',choices:['Shear buckling','Lateral buckling of a cable','Concrete crushing','Timber splitting'],answer:0,explanation:'Shear buckling and its post-buckling response are central review topics.',source:S},
{id:'ch11-rev-3',title:'Stiffener recall',level:'core',kind:'classification',q:'Which two broad stiffener roles should be distinguished?',choices:['Improving web-panel stability and carrying/localizing concentrated forces','Increasing steel density and changing yield stress','Replacing flanges and replacing welds','Only architectural decoration'],answer:0,explanation:'Intermediate and bearing/load-carrying stiffeners address different structural needs.',source:S},
{id:'ch11-rev-4',title:'Opening recall',level:'core',kind:'reasoning',q:'Why does a web opening deserve special review?',choices:['It interrupts web shear and tension-field force paths','It always strengthens the web','It removes bending from the girder','It has no structural effect'],answer:0,explanation:'Openings can significantly reduce slender-web shear and post-buckling performance.',source:S},
{id:'ch11-rev-5',title:'Alternative forms',level:'application',kind:'classification',q:'Which pairing is correct?',choices:['Corrugated web — geometric web stiffening; box girder — high torsional stiffness','Corrugated web — no shear; box girder — no bending','Hybrid girder — identical steel grades; SPSW — gravity-only system','Box girder — open section; SPSW — compression-only plate'],answer:0,explanation:'The alternative forms each address different efficiency or stability objectives.',source:S},
{id:'ch11-rev-6',title:'Final retrieval',level:'retrieval',kind:'concept',q:'Which chain best represents the complete Chapter 11 design logic?',choices:['Actions → trial geometry → flange/web resistance → plate stability/stiffeners → connections/detailing → serviceability/economy','Paint → density → colour → span','Flange only → finish','Web only → ignore supports'],answer:0,explanation:'A complete plate-girder design follows the force path from global actions through member resistance, stability and detailing.',source:S}
]);
